    if (useSSR) {
      // https://v3.router.vuejs.org/api/#router-onready
      // ssr 场景如果使用了异步组件，需要在 onReady 回调中挂载，否则 hydrate 可能会报错
      router.onReady(() => {
        app.$mount(el)
      })
    } else {
      app.$mount(el)
    }
  }
