const Service = require('@vue/cli-service')
const sharedUtils = require('@mpxjs/cli-shared-utils')
const Config = require('webpack-chain')
const PluginAPI = require('@vue/cli-service/lib/PluginAPI')

process.env.VUE_CLI_SERVICE_CONFIG_PATH = 'mpx.config.js'

Service.prototype.resolveChainableWebpackConfig = function () {
  const chainableConfig = new Config()
  // apply chains
  this.webpackChainFns.forEach(fn => {
    const res = fn(chainableConfig)
    if (res instanceof Promise) {
      this.webpackChainPromises = this.webpackChainPromises || []
      this.webpackChainPromises.push(res)
    }
  })
  return chainableConfig
}

const originResolveWebpackConfig = PluginAPI.prototype.resolveWebpackConfig
PluginAPI.prototype.resolveWebpackConfig = async function (chainableConfig) {
  chainableConfig = chainableConfig || this.resolveChainableWebpackConfig()
  if (this.service.webpackChainPromises) {
    await Promise.all(this.service.webpackChainPromises)
  }
  const res = originResolveWebpackConfig.call(this, chainableConfig)
  return res
}

PluginAPI.prototype.registerAfterResolveWebpackConfigCb = function (cb) {
  this.service.afterResolveWebpackCbs = this.afterResolveWebpackCbs || []
  this.service.afterResolveWebpackCbs.push(cb)
}

PluginAPI.prototype.runAfterResolveWebpackCallBack = async function (...args) {
  const afterResolveWebpackCbs = this.service.afterResolveWebpackCbs
  if (!afterResolveWebpackCbs || afterResolveWebpackCbs.length === 0) return
  await Promise.all(this.service.afterResolveWebpackCbs.map(fn => fn(...args)))
}

module.exports = Service

module.exports.sharedUtils = sharedUtils
const { merge } = require('webpack-merge')
const { resolveBaseRawWebpackConfig } = require('./base')
const { resolvePluginWebpackConfig } = require('./plugin')
const { SUPPORT_PLUGIN_MODE } = require('@mpxjs/cli-shared-utils')

/**
 * 强制添加一个修改webpack最终配置的方法
 * @param {*} api
 * @param {*} config
 */
function addRawConfigBeforeUserConfig (api, config) {
  api.service.webpackRawConfigFns.splice(
    api.service.webpackRawConfigFns.length - 1,
    0,
    config
  )
}

function addPluginConfig (api, options, target, webpackConfigs) {
  if (SUPPORT_PLUGIN_MODE.includes(target.mode) && api.hasPlugin('mpx-plugin-mode')) {
    webpackConfigs.push(
      resolvePluginWebpackConfig(api, merge({}, webpackConfigs[0]), target)
    )
  }
}

/**
 * 校验web的webpack配置
 * @param {*} webpackConfigs
 * @param {*} api
 * @param {*} options
 * @returns
 */
function validWebConfig (webpackConfigs, api, options) {
  const validConfig = require('@vue/cli-service/lib/util/validateWebpackConfig')
  return validConfig(webpackConfigs, api, options)
}

/**
 * 获取构建模式基础配置
 * @param { import('@vue/cli-service').PluginAPI } api
 * @param { import('@vue/cli-service').ProjectOptions } options
 * @returns
 */
async function resolveBuildWebpackConfigByTarget (api, options, target, args) {
  // 强制添加一个修改webpack配置的方法，因为webpack-chain不支持webpack5
  addRawConfigBeforeUserConfig(api, resolveBaseRawWebpackConfig(api, options, target))
  let webpackConfigs
  if (target.mode === 'web') {
    // web配置，使用vue-cli内置的方法获取配置 + mpx-cli 修改后的配置
    const resolveAppConfig = require('@vue/cli-service/lib/commands/build/resolveAppConfig')
    webpackConfigs = [await resolveAppConfig(api, args, options)]
    validWebConfig(webpackConfigs, api, options)
  } else {
    // 小程序配置，使用mpx-cli内置的配置
    webpackConfigs = [await api.resolveWebpackConfig()]
    // 小程序插件构建配置
    addPluginConfig(api, options, target, webpackConfigs)
  }
  return webpackConfigs
}

/**
 * 获取开发模式基础配置
 * @param { import('@vue/cli-service').PluginAPI } api
 * @param { import('@vue/cli-service').ProjectOptions } options
 * @returns
 */
async function resolveServeWebpackConfigByTarget (api, options, target, args) {
  // 强制添加一个修改webpack配置的方法，因为webpack-chain不支持webpack5
  addRawConfigBeforeUserConfig(api, resolveBaseRawWebpackConfig(api, options, target))
  const webpackConfigs = [await api.resolveWebpackConfig()]
  if (target.mode === 'web') {
    validWebConfig(webpackConfigs, api, options)
    return webpackConfigs[0]
  }
  // 小程序插件构建配置
  addPluginConfig(api, options, target, webpackConfigs)
  return webpackConfigs
}

module.exports.resolveBuildWebpackConfigByTarget =
  resolveBuildWebpackConfigByTarget
module.exports.resolveServeWebpackConfigByTarget =
